macro_rules! deps {
    () => {
        DefaultHashBuilder!();
        RawTable!();
        Entry!();
    };
}

macro_rules! HashMap {
    () => {
        deps!();
        # [doc = " A hash map implemented with quadratic probing and SIMD lookup."] # [doc = ""] # [doc = " The default hashing algorithm is currently [`foldhash`], though this is"] # [doc = " subject to change at any point in the future. This hash function is very"] # [doc = " fast for all types of keys, but this algorithm will typically *not* protect"] # [doc = " against attacks such as HashDoS."] # [doc = ""] # [doc = " The hashing algorithm can be replaced on a per-`HashMap` basis using the"] # [doc = " [`default`], [`with_hasher`], and [`with_capacity_and_hasher`] methods. Many"] # [doc = " alternative algorithms are available on crates.io, such as the [`fnv`] crate."] # [doc = ""] # [doc = " It is required that the keys implement the [`Eq`] and [`Hash`] traits, although"] # [doc = " this can frequently be achieved by using `#[derive(PartialEq, Eq, Hash)]`."] # [doc = " If you implement these yourself, it is important that the following"] # [doc = " property holds:"] # [doc = ""] # [doc = " ```text"] # [doc = " k1 == k2 -> hash(k1) == hash(k2)"] # [doc = " ```"] # [doc = ""] # [doc = " In other words, if two keys are equal, their hashes must be equal."] # [doc = ""] # [doc = " It is a logic error for a key to be modified in such a way that the key's"] # [doc = " hash, as determined by the [`Hash`] trait, or its equality, as determined by"] # [doc = " the [`Eq`] trait, changes while it is in the map. This is normally only"] # [doc = " possible through [`Cell`], [`RefCell`], global state, I/O, or unsafe code."] # [doc = ""] # [doc = " It is also a logic error for the [`Hash`] implementation of a key to panic."] # [doc = " This is generally only possible if the trait is implemented manually. If a"] # [doc = " panic does occur then the contents of the `HashMap` may become corrupted and"] # [doc = " some items may be dropped from the table."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashMap;"] # [doc = ""] # [doc = " // Type inference lets us omit an explicit type signature (which"] # [doc = " // would be `HashMap<String, String>` in this example)."] # [doc = " let mut book_reviews = HashMap::new();"] # [doc = ""] # [doc = " // Review some books."] # [doc = " book_reviews.insert("] # [doc = "     \"Adventures of Huckleberry Finn\".to_string(),"] # [doc = "     \"My favorite book.\".to_string(),"] # [doc = " );"] # [doc = " book_reviews.insert("] # [doc = "     \"Grimms' Fairy Tales\".to_string(),"] # [doc = "     \"Masterpiece.\".to_string(),"] # [doc = " );"] # [doc = " book_reviews.insert("] # [doc = "     \"Pride and Prejudice\".to_string(),"] # [doc = "     \"Very enjoyable.\".to_string(),"] # [doc = " );"] # [doc = " book_reviews.insert("] # [doc = "     \"The Adventures of Sherlock Holmes\".to_string(),"] # [doc = "     \"Eye lyked it alot.\".to_string(),"] # [doc = " );"] # [doc = ""] # [doc = " // Check for a specific one."] # [doc = " // When collections store owned values (String), they can still be"] # [doc = " // queried using references (&str)."] # [doc = " if !book_reviews.contains_key(\"Les Misérables\") {"] # [doc = "     println!(\"We've got {} reviews, but Les Misérables ain't one.\","] # [doc = "              book_reviews.len());"] # [doc = " }"] # [doc = ""] # [doc = " // oops, this review has a lot of spelling mistakes, let's delete it."] # [doc = " book_reviews.remove(\"The Adventures of Sherlock Holmes\");"] # [doc = ""] # [doc = " // Look up the values associated with some keys."] # [doc = " let to_find = [\"Pride and Prejudice\", \"Alice's Adventure in Wonderland\"];"] # [doc = " for &book in &to_find {"] # [doc = "     match book_reviews.get(book) {"] # [doc = "         Some(review) => println!(\"{}: {}\", book, review),"] # [doc = "         None => println!(\"{} is unreviewed.\", book)"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // Look up the value for a key (will panic if the key is not found)."] # [doc = " println!(\"Review for Jane: {}\", book_reviews[\"Pride and Prejudice\"]);"] # [doc = ""] # [doc = " // Iterate over everything."] # [doc = " for (book, review) in &book_reviews {"] # [doc = "     println!(\"{}: \\\"{}\\\"\", book, review);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " `HashMap` also implements an [`Entry API`](#method.entry), which allows"] # [doc = " for more complex methods of getting, setting, updating and removing keys and"] # [doc = " their values:"] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashMap;"] # [doc = ""] # [doc = " // type inference lets us omit an explicit type signature (which"] # [doc = " // would be `HashMap<&str, u8>` in this example)."] # [doc = " let mut player_stats = HashMap::new();"] # [doc = ""] # [doc = " fn random_stat_buff() -> u8 {"] # [doc = "     // could actually return some random value here - let's just return"] # [doc = "     // some fixed value for now"] # [doc = "     42"] # [doc = " }"] # [doc = ""] # [doc = " // insert a key only if it doesn't already exist"] # [doc = " player_stats.entry(\"health\").or_insert(100);"] # [doc = ""] # [doc = " // insert a key using a function that provides a new value only if it"] # [doc = " // doesn't already exist"] # [doc = " player_stats.entry(\"defence\").or_insert_with(random_stat_buff);"] # [doc = ""] # [doc = " // update a key, guarding against the key possibly not being set"] # [doc = " let stat = player_stats.entry(\"attack\").or_insert(100);"] # [doc = " *stat += random_stat_buff();"] # [doc = " ```"] # [doc = ""] # [doc = " The easiest way to use `HashMap` with a custom key type is to derive [`Eq`] and [`Hash`]."] # [doc = " We must also derive [`PartialEq`]."] # [doc = ""] # [doc = " [`Eq`]: https://doc.rust-lang.org/std/cmp/trait.Eq.html"] # [doc = " [`Hash`]: https://doc.rust-lang.org/std/hash/trait.Hash.html"] # [doc = " [`PartialEq`]: https://doc.rust-lang.org/std/cmp/trait.PartialEq.html"] # [doc = " [`RefCell`]: https://doc.rust-lang.org/std/cell/struct.RefCell.html"] # [doc = " [`Cell`]: https://doc.rust-lang.org/std/cell/struct.Cell.html"] # [doc = " [`default`]: #method.default"] # [doc = " [`with_hasher`]: #method.with_hasher"] # [doc = " [`with_capacity_and_hasher`]: #method.with_capacity_and_hasher"] # [doc = " [`fnv`]: https://crates.io/crates/fnv"] # [doc = " [`foldhash`]: https://crates.io/crates/foldhash"] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashMap;"] # [doc = ""] # [doc = " #[derive(Hash, Eq, PartialEq, Debug)]"] # [doc = " struct Viking {"] # [doc = "     name: String,"] # [doc = "     country: String,"] # [doc = " }"] # [doc = ""] # [doc = " impl Viking {"] # [doc = "     /// Creates a new Viking."] # [doc = "     fn new(name: &str, country: &str) -> Viking {"] # [doc = "         Viking { name: name.to_string(), country: country.to_string() }"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // Use a HashMap to store the vikings' health points."] # [doc = " let mut vikings = HashMap::new();"] # [doc = ""] # [doc = " vikings.insert(Viking::new(\"Einar\", \"Norway\"), 25);"] # [doc = " vikings.insert(Viking::new(\"Olaf\", \"Denmark\"), 24);"] # [doc = " vikings.insert(Viking::new(\"Harald\", \"Iceland\"), 12);"] # [doc = ""] # [doc = " // Use derived implementation to print the status of the vikings."] # [doc = " for (viking, health) in &vikings {"] # [doc = "     println!(\"{:?} has {} hp\", viking, health);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " A `HashMap` with fixed list of elements can be initialized from an array:"] # [doc = ""] # [doc = " ```"] # [doc = " use hashbrown::HashMap;"] # [doc = ""] # [doc = " let timber_resources: HashMap<&str, i32> = [(\"Norway\", 100), (\"Denmark\", 50), (\"Iceland\", 10)]"] # [doc = "     .into_iter().collect();"] # [doc = " // use the values stored in map"] # [doc = " ```"] pub struct HashMap < K , V , S = DefaultHashBuilder , A : Allocator = Global > { pub (crate) hash_builder : S , pub (crate) table : RawTable < (K , V) , A > , }
    };
}

HashMap!()